begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();suffix text:=substr(replace(gen_random_uuid()::text,'-',''),1,8);r jsonb;t jsonb;cfg jsonb;initial jsonb;original jsonb;rev bigint;first_rev bigint;claim_id text;
begin
 perform pg_advisory_xact_lock(17493,700);
 insert into auth.users(id,email,is_anonymous) values(a,'studio-admin-'||suffix||'@example.invalid',false),(b,'studio-player-'||suffix||'@example.invalid',false);
 insert into public.kizuna_profiles(id,username) values(a,'StudioA_'||suffix),(b,'StudioB_'||suffix);
 insert into public.kizuna_admins(user_id) values(a);
 select config into initial from public.kizuna_live_design;
 perform set_config('request.jwt.claim.sub',b::text,true);
 begin perform public.kizuna_studio('get');raise exception 'Player opened studio';exception when insufficient_privilege then null;end;
 perform public.kizuna_economy('get');
 update public.kizuna_player_states set snapshot=jsonb_set(snapshot,'{owned}','[{"id":"cseed-0013","at":1700000000000},{"id":"cseed-0014","at":1700000000001}]') where user_id=b;
 select snapshot into original from public.kizuna_player_states where user_id=b;
 perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';
 r:=public.kizuna_studio('get');cfg:=r->'draft';first_rev:=(r->>'revision')::bigint;
 cfg:=jsonb_set(cfg,'{theme}','"aurora"');
 r:=public.kizuna_studio('save',jsonb_build_object('revision',r->'revision','config',cfg));
 if r#>>'{live,theme}'<>initial->>'theme' then raise exception 'Draft leaked to public';end if;
 begin perform public.kizuna_studio('publish',jsonb_build_object('revision',first_rev));raise exception 'Stale publish';exception when raise_exception then if sqlerrm<>'REVISION_CONFLICT' then raise;end if;end;
 r:=public.kizuna_studio('publish',jsonb_build_object('revision',r->'revision'));if r#>>'{live,theme}'<>'aurora' then raise exception 'Publish failed';end if;
 cfg:=jsonb_set(cfg,'{variants}','[{"id":"qa-art","card_id":"cseed-0013","label":"Art de test","image":"https://example.com/art.webp","source":"https://example.com/artist","level":1,"enabled":true,"approved":false}]');
 r:=public.kizuna_studio('save',jsonb_build_object('revision',r->'revision','config',cfg));
 begin perform public.kizuna_studio('publish',jsonb_build_object('revision',r->'revision'));raise exception 'Unapproved art published';exception when raise_exception then if sqlerrm<>'ART_APPROVAL_REQUIRED' then raise;end if;end;
 cfg:=jsonb_set(jsonb_set(cfg,'{variants,0,approved}','true'),'{awakening,fragments}','true');
 cfg:=jsonb_set(jsonb_set(cfg,'{awakening,mode}','"selected"'),'{awakening,card_ids}','["cseed-0013"]');
 r:=public.kizuna_studio('save',jsonb_build_object('revision',r->'revision','config',cfg));r:=public.kizuna_studio('publish',jsonb_build_object('revision',r->'revision'));
 if r#>'{live,variants,0}' ? 'approved' then raise exception 'Private approval data leaked';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',b::text,true);execute 'set local role authenticated';
 begin perform public.kizuna_adventure('awaken','{"id":"cseed-0014","level":1}');raise exception 'Eligibility bypass';exception when raise_exception then if sqlerrm<>'CARD_NOT_ELIGIBLE' then raise;end if;end;
 begin perform kizuna_private.kizuna_adventure_core('awaken','{"id":"cseed-0014","level":1}');raise exception 'Core bypass';exception when insufficient_privilege then null;end;
 r:=public.kizuna_adventure('claim','{"id":"rivals-konoha"}');if r#>>'{state,fragments}'<>'1' then raise exception 'Fragment not earned';end if;
 t:=public.kizuna_adventure('claim','{"id":"rivals-konoha"}');if r->'state'<>t->'state' or r->'revision'<>t->'revision' then raise exception 'Duplicate fragment';end if;
 perform public.kizuna_adventure('visit','{"universe":"Naruto"}');r:=public.kizuna_adventure('claim','{"id":"daily-explore"}');
 begin perform public.kizuna_adventure('equip_art','{"id":"cseed-0013","variant":"qa-art"}');raise exception 'Locked art';exception when raise_exception then if sqlerrm<>'STYLE_LOCKED' then raise;end if;end;
 r:=public.kizuna_adventure('awaken','{"id":"cseed-0013","level":1,"method":"fragments"}');if r#>>'{state,fragments}'<>'0' or r#>>'{state,awakened,cseed-0013}'<>'1' then raise exception 'Fragment awakening';end if;
 t:=public.kizuna_adventure('awaken','{"id":"cseed-0013","level":1,"method":"fragments"}');if r->'state'<>t->'state' or r->'revision'<>t->'revision' then raise exception 'Duplicate awakening debit';end if;
 begin perform public.kizuna_adventure('awaken','{"id":"cseed-0013","level":2,"method":"fragments"}');raise exception 'Insufficient fragments allowed';exception when raise_exception then if sqlerrm<>'INSUFFICIENT_FRAGMENTS' then raise;end if;end;
 r:=public.kizuna_adventure('equip_art','{"id":"cseed-0013","variant":"qa-art"}');if r#>>'{state,art,cseed-0013}'<>'qa-art' then raise exception 'Equip art failed';end if;
 execute 'reset role';if original<>(select snapshot from public.kizuna_player_states where user_id=b) then raise exception 'Cosmetics changed economic snapshot';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);r:=public.kizuna_studio('get');cfg:=jsonb_set(cfg,'{features,awakening}','false');r:=public.kizuna_studio('save',jsonb_build_object('revision',r->'revision','config',cfg));r:=public.kizuna_studio('publish',jsonb_build_object('revision',r->'revision'));
 perform set_config('request.jwt.claim.sub',b::text,true);
 begin perform public.kizuna_adventure('awaken','{"id":"cseed-0013","level":2}');raise exception 'Disabled feature bypass';exception when raise_exception then if sqlerrm<>'FEATURE_DISABLED' then raise;end if;end;
 r:=public.kizuna_adventure('get');if r#>>'{state,awakened,cseed-0013}'<>'1' then raise exception 'Historical level lost';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);r:=public.kizuna_studio('get');r:=public.kizuna_studio('restore',jsonb_build_object('revision',r->'revision','target',first_rev));if r#>>'{live,features,awakening}'<>'false' or r#>>'{draft,features,awakening}'<>'true' then raise exception 'Restore published without review';end if;
 begin perform kizuna_private.studio_validate(jsonb_set(cfg,'{variants,0,image}','"javascript:alert(1)"'));raise exception 'Unsafe image';exception when raise_exception then if sqlerrm<>'INVALID_IMAGE_URL' then raise;end if;end;
 if has_function_privilege('anon','public.kizuna_studio(text,jsonb)','execute') or has_table_privilege('authenticated','kizuna_private.kizuna_studio','select,insert,update,delete') or has_table_privilege('authenticated','public.kizuna_live_design','insert,update,delete') then raise exception 'Studio grants';end if;
 update public.kizuna_admins set user_id=b where user_id=a;
 begin perform public.kizuna_studio('get');raise exception 'Revoked admin access';exception when insufficient_privilege then null;end;
end; $$;
rollback;
